import importlib.util
import itertools
import json
import random
import sys


def load(path, name):
    spec = importlib.util.spec_from_file_location(name, path)
    mod = importlib.util.module_from_spec(spec)
    sys.modules[name] = mod
    spec.loader.exec_module(mod)
    return mod


base = load("/tmp/base/dns.py", "dnsbase")
new = load("/home/c/brix5/a/task128/dns.py", "dnsnew")

random.seed(20261004)

TYPE_POOL = [1, 2, 5, 6, 15, 28, 33, 43, 46, 47, 48, 257, 255]


def rr_hex(mod, owner, t, ttl, rd):
    return {"name": mod._labels_to_name(owner), "type": t, "ttl": ttl,
            "rdata": rd.hex()}


def random_rdata(mod, t, owner, names):
    if t == 1:
        return bytes(random.randint(1, 254) for _ in range(4))
    if t == 28:
        return bytes([0x20, 1, 0x0d, 0xb8]) + bytes(random.randrange(256) for _ in range(12))
    if t in (2, 5):
        target = random.choice(names)
        return mod._encode_wire_name(target)
    if t == 6:
        return (mod._encode_wire_name(names[0])
                + mod._encode_wire_name([b"admin"] + names[-1][1:])
                + (1).to_bytes(4, "big") + (7200).to_bytes(4, "big")
                + (3600).to_bytes(4, "big") + (86400).to_bytes(4, "big")
                + (random.choice([0, 30, 60])).to_bytes(4, "big"))
    if t == 15:
        target = random.choice(names)
        return random.randrange(0, 65536).to_bytes(2, "big") + mod._encode_wire_name(target)
    if t == 33:
        target = random.choice(names)
        return (random.randrange(65536).to_bytes(2, "big")
                + random.randrange(65536).to_bytes(2, "big")
                + random.randrange(65536).to_bytes(2, "big")
                + mod._encode_wire_name(target))
    if t == 43:
        return (random.randrange(65536).to_bytes(2, "big") + bytes([8, 1])
                + bytes(random.randrange(256) for _ in range(8)))
    if t == 46:
        covered = random.choice([1, 2, 6, 15, 28])
        return mod._master_rrsig_rdata(
            covered, 13, len(owner), max(ttl_holder[0], 1),
            2000000000, 1000000000, random.randrange(65536),
            names[-1], bytes(random.randrange(1, 256) for _ in range(random.randrange(1, 12))))
    if t == 47:
        nxt = random.choice(names)
        return mod._master_nsec_rdata(nxt, [1, 2])
    if t == 48:
        return bytes([0x01, 0x01, 0x03]) + bytes(8) + bytes(random.randrange(256) for _ in range(16))
    if t == 257:
        return b"\x00\x05issue" + b'"ca.example"'
    return b"\x00"


ttl_holder = [60]


def make_zone(mod):
    origin = [b"example"]
    owners = [origin, [b"ns", b"example"], [b"www", b"example"],
              [b"a", b"example"], [b"mail", b"example"],
              [b"deep", b"sub", b"example"], [b"sub", b"example"]]
    records = []
    # exactly one SOA at apex
    records.append(rr_hex(mod, origin, 6, 100, random_rdata(mod, 6, origin, owners)))
    # apex NS
    records.append(rr_hex(mod, origin, 2, 100, mod._encode_wire_name(owners[1])))
    records.append(rr_hex(mod, owners[1], 1, 100, bytes([10, 0, 0, 1])))
    used = {(6, 0), (2, 0), (1, 1)}
    for _ in range(random.randint(3, 14)):
        oi = random.randrange(len(owners))
        t = random.choice([1, 28, 15, 33, 46, 2, 43, 48])
        if (t, oi) in used and t != 46:
            continue
        owner = owners[oi]
        ttl = random.choice([1, 30, 60, 100, 3600])
        ttl_holder[0] = ttl
        # avoid illegal CNAME combos: skip CNAME if owner has other types
        if t == 5 and any(u[1] == oi for u in used):
            continue
        records.append(rr_hex(mod, owner, t, ttl, random_rdata(mod, t, owner, owners)))
        used.add((t, oi))
    return {"version": 2, "origin": "example.", "class": 1,
            "records": records}


def make_query(mod, qname, qtype, do, edns, qclass=1, limit=512):
    out = bytearray(b"\x12\x34\x01\x00")
    out += (1).to_bytes(2, "big") + (0).to_bytes(6)
    mod._write_name(out, mod._normalize_name(qname), {})
    out += qtype.to_bytes(2, "big") + qclass.to_bytes(2, "big")
    if edns:
        ttl = 0x8000 if do else 0
        out += b"\x00" + (41).to_bytes(2, "big") + (4096).to_bytes(2, "big")
        out += ttl.to_bytes(4, "big") + (0).to_bytes(2, "big")
        out[10:12] = (1).to_bytes(2, "big")
    return bytes(out)


QNAMES = ["www.example.", "example.", "ns.example.", "a.example.",
          "mail.example.", "sub.example.", "deep.sub.example.",
          "deep.www.sub.example.", "ghost.example.", "x.y.z.example.",
          "other.", "example.org."]
QTYPES = [1, 2, 5, 6, 12, 15, 28, 33, 43, 46, 47, 48, 255, 257, 99]
LIMITS = [12, 64, 128, 256, 512, 1024, 65535]

failures = []
trials = 0
for izone in range(60):
    zobj = make_zone(new)
    try:
        zn = new.import_zone(json.dumps(zobj))
        zb = base.import_zone(json.dumps(zobj))
    except (new.ZoneError, new.RecordError, new.ConfigError) as e:
        # baseline must reject identically if new did
        try:
            base.import_zone(json.dumps(zobj))
            # new rejects but base accepts: allowed only for strict RRSIG
            rrs = [r for r in zobj["records"] if r["type"] == 46]
            bad_sig = False
            for r in rrs:
                try:
                    new._master_decode_rrsig_rdata(bytes.fromhex(r["rdata"]))
                except Exception:
                    bad_sig = True
            if not bad_sig:
                # maybe cname+rrsig allowance: check
                owners_cname = {r["name"] for r in zobj["records"] if r["type"] == 5}
                cname_rrsig = any(r["type"] == 46 and r["name"] in owners_cname
                                  for r in zobj["records"])
                if not cname_rrsig:
                    failures.append(("zone-reject-divergence", str(e), zobj))
        except Exception:
            pass
        continue

    seq = [(random.randrange(0, 400),
            (random.choice(QNAMES), random.choice(QTYPES),
             random.choice(LIMITS))) for _ in range(12)]
    seq.sort(key=lambda x: x[0])
    for edns in (False, True):
        do_vals = (False,) if not edns else (False, True)
        for do in do_vals:
            pcn = new.PositiveCache(zn)
            pcb = base.PositiveCache(zb)
            for t, (qn, qt, lim) in seq:
                qn_b = make_query(base, qn, qt, do, edns)
                qn_n = make_query(new, qn, qt, do, edns)
                try:
                    if edns:
                        rb = pcb.resolve_edns(qn_b, t, lim)
                    else:
                        rb = pcb.resolve(qn_b, t, lim)
                except Exception as eb:
                    try:
                        if edns:
                            pcn.resolve_edns(qn_n, t, lim)
                        else:
                            pcn.resolve(qn_n, t, lim)
                        failures.append((f"exception divergence {type(eb).__name__}: {eb}",
                                         qn, qt, lim, do, edns, t, izone))
                    except Exception:
                        pass
                    continue
                if edns:
                    rn = pcn.resolve_edns(qn_n, t, lim)
                else:
                    rn = pcn.resolve(qn_n, t, lim)
                trials += 1
                if rb != rn:
                    failures.append(("response divergence", qn, qt, lim, do,
                                     edns, t, izone, rb, rn))
            if pcb.stats() != pcn.stats():
                failures.append(("stats divergence", izone, edns, do,
                                 pcb.stats(), pcn.stats()))

print("trials:", trials)
if failures:
    print(len(failures), "FAILURES")
    for f in failures[:8]:
        print(f[:8])
    sys.exit(1)
print("FUZZ DIFFERENTIAL OK")

